"""Audit extract_interpolants: signature, free variables, Craig property."""
import z3
from verification.cex_minimizer import (
    PredicateRefiner, AbstractDomain, State, Transition, Counterexample,
    CEGARLoop, _atoms, _plain, _env)
from verification.experiments import cegar_exp as X


def free_consts(expr, acc=None):
    acc = set() if acc is None else acc
    if z3.is_quantifier(expr):
        free_consts(expr.body(), acc)
        return acc
    if z3.is_const(expr) and expr.decl().kind() == z3.Z3_OP_UNINTERPRETED:
        acc.add(str(expr))
    elif z3.is_app(expr):
        for ch in expr.children():
            free_consts(ch, acc)
    return acc


def has_quant(expr):
    if z3.is_quantifier(expr):
        return True
    if z3.is_app(expr):
        return any(has_quant(c) for c in expr.children())
    return False


records = []
orig = PredicateRefiner.extract_interpolants


def spy(self, cex, trans_rel, init_cond=None):
    out = orig(self, cex, trans_rel, init_cond)
    records.append((cex, list(out)))
    return out


PredicateRefiner.extract_interpolants = spy

for sysdef in X.SYSTEMS[:1] + X.SYSTEMS[2:3]:
    loop = sysdef.loop()
    res = loop.run()
    print("=== %s -> %r" % (sysdef.name, res))
    allowed = set(sysdef.var_names)
    for cex, preds in records:
        for p in preds:
            fv = free_consts(p)
            tag = ""
            if not fv <= allowed:
                tag += "  FOREIGN VARS %s" % sorted(fv - allowed)
            if has_quant(p):
                tag += "  QUANTIFIED"
            print("   pred:", p, tag)
    records[:] = []

# two positional args only
ref = PredicateRefiner(init_cond=lambda s: s["x"] == 0)
cex = Counterexample([Transition(State({"x": 0}), State({"x": 5}))])
print("two-arg call:", ref.extract_interpolants(cex, lambda s, n: n["x"] == s["x"] + 1))

"""CEGAR on a system with a nondeterministic input variable."""
import z3
from verification.cex_minimizer import CEGARLoop, CEXValidator, PredicateRefiner


def free_consts(expr, acc=None):
    acc = set() if acc is None else acc
    if z3.is_quantifier(expr):
        return free_consts(expr.body(), acc)
    if z3.is_const(expr) and expr.decl().kind() == z3.Z3_OP_UNINTERPRETED:
        acc.add(str(expr))
    elif z3.is_app(expr):
        for ch in expr.children():
            free_consts(ch, acc)
    return acc


# x += d for a fresh nondeterministic d in [1, 2]; safety x <= 4 -> unsafe.
def init(s):
    return s["x"] == 0


def trans(s, n):
    d = z3.FreshInt("d")
    return z3.And(n["x"] == s["x"] + d, d >= 1, d <= 2)


def safety(s):
    return s["x"] <= 4


loop = CEGARLoop(init, trans, safety, var_names=["x"], name="nondet", horizon=5)
res = loop.run()
print(res, "safe=%s" % res.safe, "reason=%s" % res.reason)
print("orig len", res.original_length, "min len", res.minimized_length)
print("predicates_added", res.predicates_added)
foreign = []
for p in res.predicates:
    fv = free_consts(p)
    if not fv <= {"x"}:
        foreign.append(p)
print("final predicates:", res.predicates)
print("predicates with non-program variables:", foreign)
if res.cex is not None:
    print("cex real?", CEXValidator(["x"]).validate(
        res.cex, init, trans, safety).is_real)

