"""Control: identical system with the increment inlined (no aux constant)."""
import z3, time
from verification.cex_minimizer import CEGARLoop


def init(s):
    return z3.And(s["x"] == 0, s["limit"] == 10)


def trans(s, n):
    return z3.And(s["x"] < s["limit"], n["x"] == s["x"] + 1,
                  n["limit"] == s["limit"])


def safety(s):
    return s["x"] <= 10


t = time.time()
res = CEGARLoop(init, trans, safety, var_names=["x", "limit"],
                name="inlined_counter", horizon=6, predicate_budget=50).run()
print(res, "safe=%s reason=%s" % (res.safe, res.reason))
print("predicates_added", res.predicates_added)
print("elapsed %.1fs" % (time.time() - t))

"""Randomized fuzz: build -> minimize -> re-validate over many small systems."""
import random
import z3
from verification.cex_minimizer import (
    PredicateRefiner, CEXValidator, build_trace)

random.seed(1234)

VARS = ["x", "y"]


def make_system(rng):
    """Random guarded, disjunctive linear system over x, y."""
    x0, y0 = rng.randint(-2, 3), rng.randint(-2, 3)
    mods = rng.choice([None, 3, 4, 5])
    branches = []
    for _ in range(rng.randint(1, 3)):
        dx, dy = rng.randint(-2, 2), rng.randint(-2, 2)
        guard_kind = rng.choice(["none", "lt", "gt"])
        bound = rng.randint(-3, 6)

        def branch(s, n, dx=dx, dy=dy, guard_kind=guard_kind, bound=bound,
                   mods=mods):
            parts = []
            if guard_kind == "lt":
                parts.append(s["x"] < bound)
            elif guard_kind == "gt":
                parts.append(s["x"] > bound)
            if mods:
                parts.append(n["x"] == (s["x"] + dx) % mods)
            else:
                parts.append(n["x"] == s["x"] + dx)
            parts.append(n["y"] == s["y"] + dy)
            return z3.And(*parts)
        branches.append(branch)

    def init(s, x0=x0, y0=y0):
        return z3.And(s["x"] == x0, s["y"] == y0)

    def trans(s, n, branches=branches):
        return z3.Or(*[b(s, n) for b in branches])

    kind = rng.choice(["x_ne", "sum_le", "y_le", "x_le"])
    bnd = rng.randint(-2, 5)

    def safety(s, kind=kind, bnd=bnd):
        if kind == "x_ne":
            return s["x"] != bnd
        if kind == "sum_le":
            return s["x"] + s["y"] <= bnd
        if kind == "y_le":
            return s["y"] <= bnd
        return s["x"] <= bnd
    return init, trans, safety


empty_out = 0
other_bad = 0
checked = 0
lengths_ok = True
for trial in range(120):
    init, trans, safety = make_system(random)
    for horizon in (2, 4, 7):
        try:
            cex = build_trace(VARS, init, trans, safety, horizon,
                              max_horizon=horizon)
        except Exception as exc:
            print("build failed:", exc)
            continue
        if cex is None:
            continue
        val = CEXValidator(VARS)
        if not val.validate(cex, init, trans, safety).is_real:
            continue
        ref = PredicateRefiner(init_cond=init, safety=safety)
        before_states = list(cex.states)
        mini = ref.minimize_cex(cex, trans)
        checked += 1
        if mini.length > cex.length:
            lengths_ok = False
            print("LENGTHENED", trial, horizon, cex.length, mini.length)
        if list(cex.states) != before_states:
            print("INPUT MUTATED", trial, horizon)
        res = val.validate(mini, init, trans, safety)
        if not res.is_real:
            if res.stage == "empty":
                empty_out += 1
                if empty_out <= 2:
                    print("EMPTY OUT trial=%d h=%d in=%s" % (
                        trial, horizon, before_states))
            else:
                other_bad += 1
                print("BROKEN(%s) trial=%d h=%d\n  in =%s\n  out=%s\n  reason=%s"
                      % (res.stage, trial, horizon, before_states,
                         mini.states, res.reason))
print("checked=%d  empty_output=%d  other_invalid=%d  lengths_ok=%s"
      % (checked, empty_out, other_bad, lengths_ok))

"""Stress the loop-cut guard: cyclic systems whose initial state is bad."""
import random
import z3
from verification.cex_minimizer import (
    PredicateRefiner, CEXValidator, build_trace)

random.seed(99)
VARS = ["x", "y"]
checked = broken = lengthened = empties = 0

for trial in range(200):
    mod = random.choice([2, 3, 4, 5, 6])
    dx = random.choice([1, 2, 3])
    dy = random.choice([0, 1, -1])
    bad = random.randint(0, mod - 1)
    ystart = random.randint(0, 2)
    allow_stutter = random.random() < 0.5
    allow_double = random.random() < 0.5

    def init(s, ystart=ystart):
        return z3.And(s["x"] == 0, s["y"] == ystart)

    def trans(s, n, mod=mod, dx=dx, dy=dy, allow_stutter=allow_stutter,
              allow_double=allow_double):
        opts = [z3.And(n["x"] == (s["x"] + dx) % mod, n["y"] == s["y"] + dy)]
        if allow_double:
            opts.append(z3.And(n["x"] == (s["x"] + 2 * dx) % mod,
                               n["y"] == s["y"] + dy))
        if allow_stutter:
            opts.append(z3.And(n["x"] == s["x"], n["y"] == s["y"]))
        return z3.Or(*opts)

    def safety(s, bad=bad):
        return s["x"] != bad

    for horizon in (2, 3, 5, 8):
        cex = build_trace(VARS, init, trans, safety, horizon, max_horizon=horizon)
        if cex is None:
            continue
        val = CEXValidator(VARS)
        if not val.validate(cex, init, trans, safety).is_real:
            continue
        ref = PredicateRefiner(init_cond=init, safety=safety)
        mini = ref.minimize_cex(cex, trans)
        checked += 1
        if mini.length > cex.length:
            lengthened += 1
            print("LENGTHENED", cex.states, "->", mini.states)
        if mini.length == 0:
            empties += 1
        res = val.validate(mini, init, trans, safety)
        if not res.is_real:
            broken += 1
            if broken <= 4:
                print("BROKEN(%s) mod=%d dx=%d bad=%d\n  in =%s\n  out=%s\n  %s"
                      % (res.stage, mod, dx, bad, cex.states, mini.states,
                         res.reason))
print("checked=%d broken=%d lengthened=%d empty=%d"
      % (checked, broken, lengthened, empties))

"""Independently re-verify every interpolant candidate: A->I, I&B unsat, vocab."""
import z3
from verification.cex_minimizer import PredicateRefiner
from verification.experiments import cegar_exp as X


def free_consts(expr, acc=None):
    acc = set() if acc is None else acc
    if z3.is_quantifier(expr):
        return free_consts(expr.body(), acc)
    if z3.is_const(expr) and expr.decl().kind() == z3.Z3_OP_UNINTERPRETED:
        acc.add(str(expr))
    elif z3.is_app(expr):
        for ch in expr.children():
            free_consts(ch, acc)
    return acc


stats = {"n": 0, "bad_implies": 0, "bad_unsat": 0, "bad_vocab": 0, "quant": 0}
orig = PredicateRefiner._interpolate


def spy(self, fa, fb, local_env):
    out = orig(self, fa, fb, local_env)
    if out is None:
        return out
    stats["n"] += 1
    s = z3.Solver()
    s.add(z3.Not(z3.Implies(fa, out)))
    if s.check() != z3.unsat:
        stats["bad_implies"] += 1
    s = z3.Solver()
    s.add(out, fb)
    if s.check() != z3.unsat:
        stats["bad_unsat"] += 1
    va, vb, vi = free_consts(fa), free_consts(fb), free_consts(out)
    if not vi <= (va & vb):
        stats["bad_vocab"] += 1
        print("   VOCAB VIOLATION: I mentions %s, shared(A,B)=%s"
              % (sorted(vi - (va & vb)), sorted(va & vb)))
    if z3.is_quantifier(out) or (z3.is_app(out)
                                 and any(z3.is_quantifier(c)
                                         for c in out.children())):
        stats["quant"] += 1
    return out


PredicateRefiner._interpolate = spy

for sysdef in X.SYSTEMS:
    res = sysdef.loop().run()
    print("%-18s %r" % (sysdef.name, res))
print(stats)

