"""Unsafe only via MIXED nondeterministic increments: does CEGAR say safe?"""
import z3
from verification.cex_minimizer import (
    CEGARLoop, build_trace, CEXValidator, SystemAbstraction, AbstractDomain,
    collect_var_names)


def init(s):
    return z3.And(s["x"] == 0)


def trans(s, n):
    d = z3.FreshInt("d")
    return z3.And(z3.Or(d == 2, d == 3), n["x"] == s["x"] + d)


def safety(s):
    return s["x"] != 5


# ground truth: x = 5 is reachable (2 then 3), so the system is UNSAFE.
cex = build_trace(["x"], init, trans, safety, 2, max_horizon=6)
print("concrete BMC witness:", cex and cex.states)
print("witness real?", cex is not None and CEXValidator(["x"]).validate(
    cex, init, trans, safety).is_real)

res = CEGARLoop(init, trans, safety, var_names=["x"], name="mixed",
                horizon=2, max_iterations=8).run()
print(res, "safe=%s reason=%s" % (res.safe, res.reason))

# Show what the fully-restored abstraction looks like over two steps.
dom = AbstractDomain()
abst = SystemAbstraction(["x"], init, trans, safety, dom)
for _ in range(len(abst.conjuncts)):
    abst.restore_any()
t = abst.abstract_trans()
e0 = {"x": z3.Int("x0")}
e1 = {"x": z3.Int("x1")}
e2 = {"x": z3.Int("x2")}
print("abstract 2-step formula:", z3.And(t(e0, e1), t(e1, e2)))
s = z3.Solver()
s.add(init(e0), t(e0, e1), t(e1, e2), z3.Not(safety(e2)))
print("abstract system can reach x=5 in 2 steps?", s.check())
